/* A shared market scene. Inventory remains owned by the existing transactional API. */
(()=>{
 const greetings={wave:'👋 안녕!',thanks:'💛 고마워!',together:'🌱 같이 도와주자!'};
 let visitors=[],spot=8,selected='',page=0,lastKey='',lastDetailKey='',activeToken='',busy=false,timer=null,notice='친구들의 방문을 확인하고 있어요.',lastGreeting=0,wasMarket=false,scene3d=null,scene3dLoading=null,lastOwner='',lastHistory='',tradeInProgress=false,joinedPresence=false;const awayVisitors=new Map();const visibleVisitors=()=>[...visitors,...awayVisitors.values()];
 const active=()=>window.classroomActive&&document.body.dataset.screen==='market'&&!document.hidden;
 const esc=escapeHtml;
 const hash=id=>Array.from(id).reduce((n,c)=>n+c.charCodeAt(0),0);
 const avatar=(id,me=false)=>`<span class="market-person ${me?'is-me':''}" style="--shirt:${['#527ea0','#ca775c','#81924e','#ab78a1'][hash(id)%4]}"><i class="person-hair"></i><i class="person-face"></i><i class="person-body"></i><i class="person-legs"></i></span>`;
 function syncScene(){const root=document.querySelector('#marketSquare');if(!root||!window.classroomActive||document.body.dataset.screen!=='market')return;const data={root,me:classroomData.me,trial:!!state.trial,visitors:visibleVisitors(),shown:[...root.querySelectorAll('.market-stall[data-market-peer]')].map(button=>({id:button.dataset.marketPeer})),spot};if(scene3d){scene3d.update(data);return}if(scene3dLoading)return;scene3dLoading=import('./market-scene3d.js').then(({createMarketScene})=>{scene3d=createMarketScene({onPeer:selectPeer,onSpot:index=>{spot=index;position();sync()}});scene3d.update(data)}).catch(error=>console.warn('3D market unavailable; keeping 2D market',error));}
 function selectPeer(id){selected=id;const v=visitors.find(row=>row.id===id);spot=v?(v.spot+2)%12:6;draw()}
 function detail(){
  const d=classroomData,peer=d.players?.find(p=>p.id===selected),here=visitors.some(p=>p.id===selected),offers=(d.offers||[]).filter(o=>o.seller===selected);
  if(!peer)return '<b>함께 걷고, 서로의 물건을 나눠요</b><p>친구나 가판대를 누르면 가까이 가서 물건을 볼 수 있어요.</p>';
  return `<b>${esc(peer.name)}${selected===d.me.id?' · 나':''}</b><span class="market-presence-state">${here?'지금 장터에 있어요':state.trial&&selected!==d.me.id?'연습 친구 · 실제 접속자가 아니에요':offers.length?'지금은 물건만 맡겨 두었어요':'지금은 자리를 비웠어요'}</span>${offers.length?offers.map(o=>`<div class="market-goods"><span>${symbols[o.give_item]} ${items[o.give_item]} ${o.give_qty}개 <b>↔</b> ${symbols[o.want_item]} ${items[o.want_item]} ${o.want_qty}개</span><button data-market-trade="${esc(o.id)}" ${(!d.room.market&&o.seller!==d.me.id)||schoolPending?'disabled':''}>${o.seller===d.me.id?'제안 취소':'마주 보고 교환'}</button></div>`).join(''):'<p>아직 맡겨 둔 물건은 없어요. 인사를 건네 보세요.</p>'}`;
 }
 function draw(){
  if(!window.classroomActive||document.body.dataset.screen!=='market')return;
  const d=classroomData;if(!d?.me)return;const history=state.history?.[0]||'';if(lastOwner!==d.me.id){lastOwner=d.me.id;lastHistory=history}else if(history!==lastHistory){lastHistory=history;if(!tradeInProgress&&/교환했어요/.test(history))notice=history}
  let root=document.querySelector('#marketSquare');if(!root){$('#panel').innerHTML='<section id="marketSquare" aria-label="함께 만나는 장터"></section>';root=$('#marketSquare');lastKey='';lastDetailKey=''}
  const seen=visibleVisitors(),peers=[...new Map([...(d.offers||[]).map(o=>({id:o.seller,name:o.seller_name})),...seen].map(p=>[p.id,p])).values()].filter(p=>p.id!==d.me.id);
  const pages=Math.max(1,Math.ceil(peers.length/(innerWidth<850?3:6)));page=Math.min(page,pages-1);const perPage=innerWidth<850?3:6,shown=peers.slice(page*perPage,page*perPage+perPage);
  const used=new Set(),positions=new Map();for(const p of shown){const v=seen.find(v=>v.id===p.id);if(v){let pos=v.spot;while(used.has(pos))pos=(pos+1)%12;used.add(pos);positions.set(p.id,pos)}}
  const key=JSON.stringify([d.me.id,d.me.version,d.room.market,d.room.paused,d.offers,d.shipping,seen,selected,page,notice,schoolPending]);
  if(key===lastKey){position();return}lastKey=key;const previousHero=$('#marketHero'),previousDetail=root.querySelector('.market-detail'),detailKey=JSON.stringify([selected,(d.offers||[]).filter(o=>o.seller===selected),visitors.some(v=>v.id===selected),d.room.market,d.room.paused,schoolPending,state.trial]);
  root.innerHTML=`<div class="market-heading"><div><small>SHINY VILLAGE · 우리 반 만남의 광장</small><h2>반가워, 장터에서 만나!</h2><p>${d.room.market?'가판대에 물건을 맡기고 친구에게 인사해요.':'지금은 장터 준비 시간이에요. 친구와 인사는 할 수 있어요.'}</p></div><span class="market-count">${joinedPresence?`함께 있는 ${visitors.length}명${awayVisitors.size?` · 자리 비움 ${awayVisitors.size}명`:''}`:'장터 연결 중…'}</span></div>
  <div class="market-toolbar"><button data-market-return>← 마을로</button><button id="newSchoolOffer" ${!d.room.market||d.room.paused?'disabled':''}>＋ 내 가판대에 물건 놓기</button><button data-market-mine>내 물건 보기</button><span id="marketSync" role="status">${esc(notice)}</span></div>
  <div class="market-plaza" aria-label="장터 광장"><div class="market-trees" aria-hidden="true">🌳 🌳</div><div class="market-sign" aria-hidden="true">우리의 작은 장터</div><div class="market-path" aria-hidden="true"></div>
  <div class="market-stalls">${Array.from({length:perPage},(_,i)=>{const p=shown[i],o=p&&(d.offers||[]).find(o=>o.seller===p.id),online=p&&visitors.some(v=>v.id===p.id);return p?`<button class="market-stall ${selected===p.id?'chosen':''}" data-market-peer="${esc(p.id)}"><span class="stall-awning" aria-hidden="true"></span><span class="stall-goods" aria-hidden="true">${o?symbols[o.give_item]+' '+symbols[o.want_item]:'🧺'}</span><b>${esc(p.name)}의 가판대</b><small>${online?'● 함께 있어요':state.trial?'연습 친구의 가판대':'물건만 맡김'}</small></button>`:'<div class="market-stall vacant"><span class="stall-awning"></span><span class="stall-goods">🧺</span><small>이웃의 가판대 자리</small></div>'}).join('')}</div>
  <div class="market-walk-spots">${Array.from({length:12},(_,i)=>`<button data-market-spot="${i}" aria-label="광장 ${i+1}번 자리로 걷기" style="left:${19+(i%6)*14}%;top:${67+Math.floor(i/6)*18}%"><span aria-hidden="true">·</span></button>`).join('')}</div>
  ${shown.filter(p=>seen.some(v=>v.id===p.id)).map((p,i)=>{const v=seen.find(v=>v.id===p.id),pos=positions.get(p.id);return `<button class="market-visitor ${v.away?'away':''}" data-market-peer="${esc(p.id)}" style="left:${8+(pos%6)*16}%;top:${51+Math.floor(pos/6)*18}%" aria-label="${esc(p.name)}${v.away?' 자리 비움':'에게 다가가기'}">${avatar(p.id)}<span class="visitor-name">${esc(p.name)}${v.away?' · 자리 비움':''}</span>${v.greeting?`<span class="market-greeting">${greetings[v.greeting]||''}</span>`:''}</button>`}).join('')}
  <div class="market-hero" id="marketHero">${avatar(d.me.id,true)}<span class="visitor-name">${esc(state.name)} · 나</span></div><div class="plaza-caption">발자국 자리를 눌러 걸어요 · 친구를 눌러 만나요</div></div>
  <div class="market-bottom"><div class="market-emotes" aria-label="친구에게 인사">${Object.entries(greetings).map(([id,text])=>`<button data-market-greet="${id}" ${d.room.paused?'disabled':''}>${text}</button>`).join('')}</div>${pages>1?`<div class="market-paging"><button data-market-page="-1" ${page===0?'disabled':''}>이전 이웃</button><span>${page+1}/${pages}</span><button data-market-page="1" ${page===pages-1?'disabled':''}>다음 이웃</button></div>`:''}</div>${coldChainPanel(true)}<section class="market-detail" aria-label="선택한 친구와 물건">${detail()}</section><p class="market-note">방문·인사는 보통 5초 안팎에 반영돼요. 자리를 잠시 비우면 '자리 비움'으로 표시되고, 맡긴 물건은 남아요.${state.trial?' 연습 친구는 실제 접속자가 아닙니다.':''}</p>`;
  if(state.trial){const guide=shown.find(p=>!visitors.some(v=>v.id===p.id));if(guide){const marker=document.createElement('button');marker.className='market-visitor market-practice-visitor';marker.dataset.marketPeer=guide.id;marker.setAttribute('aria-label','연습 친구에게 다가가기');marker.innerHTML='<span class="visitor-name">연습 친구</span>';root.querySelector('.market-plaza').append(marker)}}
  if(previousHero)$('#marketHero').replaceWith(previousHero);
  if(previousDetail&&lastDetailKey===detailKey)root.querySelector('.market-detail').replaceWith(previousDetail);lastDetailKey=detailKey;
  const selfGreeting=visitors.find(p=>p.id===d.me.id)?.greeting;$('#marketHero .market-greeting')?.remove();if(selfGreeting){const bubble=document.createElement('span');bubble.className='market-greeting';bubble.textContent=greetings[selfGreeting];$('#marketHero').append(bubble)}
  $('#newSchoolOffer').onclick=newSchoolOffer;
  root.onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-market-return')){window.villageNavigate('village');return}if(b.dataset.marketPeer){e.preventDefault();selectPeer(b.dataset.marketPeer);return}
   if(b.hasAttribute('data-market-mine')){selected=d.me.id;draw()}
   if(b.dataset.marketSpot!==undefined){spot=Number(b.dataset.marketSpot);position();sync()}
   if(b.dataset.marketGreet){sendGreeting(b.dataset.marketGreet)}
   if(b.dataset.marketTrade){trade(b.dataset.marketTrade)}
   if(b.dataset.marketPage){page+=Number(b.dataset.marketPage);draw()}
  };position();
 }
 function position(){const h=$('#marketHero');if(h){h.style.left=(19+(spot%6)*14)+'%';h.style.top=(67+Math.floor(spot/6)*18)+'%'}syncScene()}
 async function sync(greeting){if(!active()||busy)return;const token=schoolToken;busy=true;activeToken=token;try{const d=await schoolFetch('/api/market-presence',{action:greeting?'greet':'visit',...(greeting?{greeting}:{spot})},token);if(active()&&schoolToken===token){const now=Date.now(),present=new Set(d.visitors.map(v=>v.id));for(const old of visitors)if(old.id!==d.me&&!present.has(old.id)&&!awayVisitors.has(old.id))awayVisitors.set(old.id,{...old,away:true,until:now+90000,greeting:''});for(const id of present)awayVisitors.delete(id);for(const [id,row] of awayVisitors)if(row.until<=now)awayVisitors.delete(id);visitors=d.visitors;joinedPresence=true;const self=visitors.find(v=>v.id===d.me);if(self)spot=self.spot;draw()}}catch(e){notice=e.message||'방문 상태를 확인하지 못했어요';draw()}finally{busy=false;if(!active()||schoolToken!==token){await leave(token)}}}
 async function leave(token=activeToken){if(!token)return;activeToken='';visitors=[];awayVisitors.clear();joinedPresence=false;try{await schoolFetch('/api/market-presence',{action:'leave'},token)}catch{} }
 async function sendGreeting(g){if(Date.now()-lastGreeting<5000){toast('인사는 5초 뒤에 다시 보낼 수 있어요.');return}if(busy){toast('입장을 확인하고 있어요. 잠시 뒤 인사해 주세요.');return}lastGreeting=Date.now();notice='인사를 보냈어요. 친구 화면에 곧 전달됩니다.';draw();await sync(g);toast('인사를 보냈어요. 친구 화면에 곧 전달됩니다.')}
 function trade(id){
  const o=classroomData.offers.find(o=>o.id===id);if(!o)return;
  const own=o.seller===classroomData.me.id,here=visitors.some(v=>v.id===o.seller),showFlat=!document.querySelector('.market-plaza.market-3d');
  const have=schoolTradeStock(o.want_item),short=!own&&have<o.want_qty;
  modal(`<h2>${own?'가판대에서 물건을 가져올까요?':'서로의 물건을 확인해요'}</h2><div class="market-meeting"><div>${showFlat?avatar(classroomData.me.id,true):''}<b>${esc(state.name)}</b><span>${symbols[o.want_item]} ${items[o.want_item]} ${o.want_qty}개${own?'':` · <span id="marketMeetingStock">내 보관함 ${have}개</span>`}</span></div><span class="meeting-arrow">↔</span><div>${showFlat?avatar(o.seller):''}<b>${esc(o.seller_name)}</b><span>${symbols[o.give_item]} ${items[o.give_item]} ${o.give_qty}개</span></div></div><p>${own?'맡겨 둔 물건이 내 보관함으로 돌아옵니다.':here?'친구가 올린 제안에 내가 동의하면 교환됩니다.':'친구가 미리 맡긴 물건이에요. 지금 자리에 없어도 제안대로 교환할 수 있어요.'}</p><p id="marketDialogFeedback" role="alert" class="school-error">${short?'교환할 물건이 부족해요.':''}</p><div class="dialog-actions"><button data-close>돌아가기</button><button id="confirmSchoolTrade" class="primary" ${short?'disabled':''}>${own?'제안 취소하기':'이 물건으로 교환하기'}</button></div>`);$('#dialog').dataset.marketOffer=id;
  $('#confirmSchoolTrade').onclick=async()=>{const button=$('#confirmSchoolTrade'),feedback=$('#marketDialogFeedback');button.disabled=true;button.textContent='교환 확인 중…';feedback.textContent='교환을 저장하고 있어요.';tradeInProgress=true;const ok=await schoolAction({action:own?'cancel':'accept',offer:id},true);tradeInProgress=false;if(ok){close();notice=own?'물건을 보관함으로 가져왔어요':'🎁 물건이 서로의 보관함으로 건너갔어요!';draw();const root=$('#marketSquare');root?.classList.add('trade-complete');setTimeout(()=>root?.classList.remove('trade-complete'),1500);toast(notice)}else{feedback.textContent=window.schoolLastActionError||'교환을 마치지 못했어요. 다시 시도해 주세요.';button.disabled=false;button.textContent=own?'제안 취소하기':'이 물건으로 교환하기'}};
 }
 const previous=renderPanel;renderPanel=function(){if(window.classroomActive&&document.body.dataset.screen==='market'){draw();return}previous()};
 function changed(){if(active()){draw();if(!wasMarket){const root=$('#marketSquare');root?.classList.remove('market-arriving');void root?.offsetWidth;root?.classList.add('market-arriving');const heading=root?.querySelector('h2');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}wasMarket=true;sync()}else{wasMarket=false;leave()}}
 window.addEventListener('resize',()=>{lastKey='';draw()});window.addEventListener('village-screen-change',changed);document.addEventListener('visibilitychange',changed);
 window.addEventListener('pagehide',()=>{if(activeToken)fetch('/api/market-presence',{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+activeToken},body:JSON.stringify({action:'leave'}),keepalive:true}).catch(()=>{})});
 async function tick(){if(active()){await sync();if(active())await refreshSchool()}else if(activeToken)await leave();timer=setTimeout(tick,4500+Math.random()*1000)}
 // One completion-based heartbeat, independent of frequent scene rendering.
 timer=setTimeout(tick,500);window.addEventListener('village-screen-change',()=>{if(!timer)timer=setTimeout(tick,500)});
 changed();
})();
